def simulate(events, age, observer=None):
    fdb = {}  # (vlan, mac) -> [port, seen]
    if observer is not None:  # record/replay：逐事件记录 applied
        observer["items"] = []
    for t, port, mac, vlan in events:
        # 事件前该 (vlan, mac) 的 [port, seen]（不存在为 None）
        previous = tuple(fdb[(vlan, mac)]) if (vlan, mac) in fdb else None
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        fdb[(vlan, mac)] = [port, t]
        if observer is not None:
            # 含 port、seen 的表项与事件前不同（新学习、迁移或 seen 推进）
            # 才 applied；同时刻同口重复学习幂等，applied=False
            applied = previous != (port, t)
            observer["items"].append(
                {"kind": "learn", "t": t, "applied": applied, "output": None}
            )
    entries = []
    for (vlan, mac), (port, seen) in sorted(fdb.items(), key=lambda item: item[0]):
        entries.append(
            {"vlan": vlan, "mac": mac, "port": port, "seen": seen}
        )
    return {"fdb": entries}


